open.example:
const { Dialogue } = kcds.characters;
const { Events } = kcds.core;

const firstPage = {
  line: 'What brings you to the mill?',
  options: [
    { id: 'work', text: 'I am looking for work.' },
    { id: 'bye', text: 'Nothing. Farewell.' },
  ],
};
Dialogue.open(player, firstPage, { npc: miller });

Events.on('dialogueChoice', (session, speaker, optionId) => {
  if (optionId === 'bye') {
    Dialogue.close(session);
    return;
  }
  Dialogue.update(session, { line: 'Carry these sacks.', options: [{ id: 'bye', text: 'Right away.' }] });
});

open.exampleCs:
var firstPage = new { line = "What brings you to the mill?", options = new object[] { new { id = "work", text = "I am looking for work." }, new { id = "bye", text = "Nothing. Farewell." } } };
Dialogue.Open(player, firstPage, new { npc = miller });

Events.On("dialogueChoice", (JsValue session, Player speaker, JsValue optionId) =>
{
    if (optionId.AsString() == "bye")
    {
        Dialogue.Close(session);
        return;
    }
    Dialogue.Update(session, new { line = "Carry these sacks.", options = new object[] { new { id = "bye", text = "Right away." } } });
});

